/* Steps: Q / W / E / R show the ability icon (optional label in brackets: "Q[1]"), anything else shows as text */
const COMBOS = [
  { name: "Fast Q", steps: ["Auto", "Q[1]", "Auto", "Q[2]", "Auto", "Q[3]", "Auto"],
    desc: "Auto, then Q right away, then right-click the ground away from the enemy to cancel the Q animation. Repeat for all three Qs. The core Riven mechanic." },
  { name: "Shy combo", steps: ["E", "R[1]", "Flash", "W", "Auto", "Hydra", "R[2]", "Q[3]"],
    desc: "The burst combo to one-shot a target from range. Hydra or Tiamat if you have one, otherwise skip that step. A slower but easier variant uses Hydra before W." },
  { name: "Wehrli combo", steps: ["R[2]", "E", "Flash", "W", "Q[3]"],
    desc: "With R1 already active: cast Wind Slash, then E and Flash in and W into Q3 so they hit before the Wind Slash lands. Wind Slash does more damage the lower they are, so it hits for more." },
  { name: "E into R", steps: ["E", "R[1]"],
    desc: "Cast R during the E dash to hide the R animation." },
  { name: "E into W", steps: ["E", "W"],
    desc: "Cast W at the end of the E dash for an instant stun on arrival." },
  { name: "R2 into W", steps: ["R[2]", "W"],
    desc: "Wind Slash, then W instantly so they're stunned and can't dodge the Wind Slash." },
  { name: "Q3 Flash", steps: ["Q[3]", "Flash"],
    desc: "Flash during the Q3 leap; the knock-up lands right where you flash, too fast to react to." },
  { name: "Flash W", steps: ["Flash", "W"],
    desc: "Flash then W instantly for a stun they can't react to. Your W range is short, so this is how you land it from range." }
];

/* No ult dodge list for Riven */
const DODGES = [];

const COLUMNS = [
  { key: "champion",     label: "Champion",       cls: "col-champ" },
  { key: "difficulty",   label: "Difficulty",     cls: "col-narrow" },
  { key: "keystone",     label: "Setup",          cls: "col-setup" },  // keystone + start + summoners
  { key: "lanePlan",     label: "Lane plan (1–6)",cls: "col-wide" },
  { key: "dodge",        label: "Key ability",    cls: "col-mid" },
  { key: "spikes",       label: "Power spikes",   cls: "col-mid" },
  { key: "winCondition", label: "Win condition",  cls: "col-mid" },
  { key: "notes",        label: "Tips",           cls: "col-tips" }
];

const normName = s => { const n = String(s).toLowerCase().replace(/[^a-z]/g, ""); return n === "monkeyking" ? "wukong" : n; };
const myRec = m => MY_DATA && MY_DATA.byOpponent[normName(m.champion)];

const state = { search: "", filter: "all", sortKey: "champion", sortDir: 1 };

const $ = (sel) => document.querySelector(sel);
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, c => ({ "&":"&amp;", "<":"&lt;", ">":"&gt;", '"':"&quot;", "'":"&#39;" }[c]));

/* Icons for every item named in `text`, in reading order (longest name wins on overlaps) */
const ITEM_NAMES = Object.keys(ICONS.item).sort((a, b) => b.length - a.length);
function itemIcons(text) {
  const taken = [], hits = [];
  for (const name of ITEM_NAMES) {
    let i = text.indexOf(name);
    while (i >= 0) {
      const end = i + name.length;
      if (!taken.some(([s, e]) => i < e && end > s)) { taken.push([i, end]); hits.push([i, name]); }
      i = text.indexOf(name, end);
    }
  }
  return hits.sort((a, b) => a[0] - b[0]).map(([, n]) => `<img class="ico ico-item" src="${ICONS.item[n]}" alt="" title="${esc(n)}">`).join("");
}
const champIcon = name => ICONS.champ[name] ? `<img class="ico ico-champ" src="${ICONS.champ[name]}" alt="">` : "";
const ksIcon = name => ICONS.rune && ICONS.rune[name] ? `<img class="ico ico-rune" src="${ICONS.rune[name]}" alt="">` : "";
const tier = (d) => d <= 2 ? "easy" : d === 3 ? "even" : d === 4 ? "hard" : "vhard";
const tierLabel = { easy: "Easy", even: "Even", hard: "Hard", vhard: "Very hard" };

/* ---------- Theme ---------- */
(function initTheme() {
  let saved = null;
  try { saved = localStorage.getItem("guides-theme"); } catch (e) {}
  if (saved) document.documentElement.dataset.theme = saved;
  $("#themeToggle").addEventListener("click", () => {
    const current = document.documentElement.dataset.theme ||
      (matchMedia("(prefers-color-scheme: light)").matches ? "light" : "dark");
    const next = current === "light" ? "dark" : "light";
    document.documentElement.dataset.theme = next;
    try { localStorage.setItem("guides-theme", next); } catch (e) {}
  });
})();

/* ---------- Static sections ---------- */
function renderKit() {
  $("#kitGrid").innerHTML = KIT.map(k => `
    <article class="card">
      ${ICONS.ability[k.key]
        ? `<div class="ability"><img src="${ICONS.ability[k.key]}" alt="${esc(k.name)} icon"><b>${k.key}</b></div>`
        : `<div class="key"><span>${k.key}</span></div>`}
      <div class="sub">${esc(k.sub)}</div>
      <h3>${esc(k.name)}</h3>
      <p>${esc(k.desc)}</p>
      <div class="tip"><b>Tip:</b> ${esc(k.tip)}</div>
    </article>`).join("");
}

function renderCombos() {
  const step = s => {
    const [, key, lbl] = s.match(/^([QWER])(?:\[(.+)\])?$/) || [];
    if (key && ICONS.ability[key]) return `<span class="step" title="${key}${lbl || ""}"><img src="${ICONS.ability[key]}" alt="${key}${lbl || ""}">${lbl ? `<b>${esc(lbl)}</b>` : ""}</span>`;
    return `<span class="step-txt">${esc(key ? key + (lbl || "") : s)}</span>`;
  };
  $("#comboGrid").innerHTML = COMBOS.map(c => `
    <div class="card">
      <h3>${esc(c.name)}</h3>
      <div class="combo-seq">${c.steps.map(step).join(`<span class="arr">→</span>`)}</div>
      <p>${esc(c.desc)}</p>
    </div>`).join("");
  $("#dodgeGrid").innerHTML = DODGES.map(d => `
    <div class="card">
      <h3>${d.ability && ICONS.ability[d.ability] ? `<img src="${ICONS.ability[d.ability]}" alt="" style="width:26px;height:26px;border-radius:4px;vertical-align:-7px;margin-right:8px">` : ""}${esc(d.title)}</h3>
      <ul class="dodge-list">${d.rows.map(([c, t]) => `<li>${ICONS.champ[c] ? `<img src="${ICONS.champ[c]}" alt="">` : ""}<span><b>${esc(c)}:</b> ${esc(t)}</span></li>`).join("")}</ul>
    </div>`).join("");
}

const ANTI_HEAL = ["Executioner's Calling", "Chempunk Chainsword", "Mortal Reminder", "Thornmail", "Bramble Vest", "Oblivion Orb", "Morellonomicon"];

/* Build shown on the page: from your games when MY_DATA exists, else the BUILD defaults. */
function activeBuild() {
  const withSec = r => { const s = BUILD.runeSecondary[r.name]; return s ? { ...r, secondaryTree: s.tree, secondary: s.runes } : r; };
  // Pages with `sameAs` copy that page and only swap the keystone
  const copyPages = pages => pages.map((p, i) => {
    const r = BUILD.runes[i];
    if (!r.sameAs) return p;
    const base = pages.find(x => x.name === r.sameAs);
    return { ...base, name: r.name, when: r.when, primary: [r.name, ...base.primary.slice(1)] };
  });
  if (!MY_DATA) return { ...BUILD, runes: copyPages(BUILD.runes.map(withSec)) };
  const d = MY_DATA;
  // Reuse the guide's short descriptions where your item/rune matches one of the defaults
  const hint = (list, name) => (list.find(([n]) => n.split(" / ").some(x => x === name)) || [])[1] || "";
  // Opening is fixed (Tri → Rav or Rav → Tri); only the 3rd item comes from your games
  const third = (d.thirdItem || []).filter(n => n !== "Trinity Force" && n !== "Ravenous Hydra");
  const core = [...BUILD.core.slice(0, 2), third.length ? [third.slice(0, 2).join(" / "), "3rd item: Sterak's into true damage / CC, Death's Dance into burst"] : BUILD.core[2]];
  const skillOrder = d.skillOrder && d.skillOrder.length ? d.skillOrder : BUILD.skillOrder;
  // Max order = order in which Q/W/E reach 5 points (falls back to most points)
  const maxAt = s => { let n = 0; const i = skillOrder.findIndex(x => x === s && ++n === 5); return i < 0 ? 99 - skillOrder.filter(x => x === s).length : i; };
  return {
    // The guide's keystones, with primary runes and shards taken from your games when available
    // Rune pages are set by hand in BUILD (with click-to-swap options), not taken from match data
    runes: copyPages(BUILD.runes.map(withSec)),
    starting: BUILD.starting,
    core,
    boots: [...new Set([...d.boots, ...BUILD.extraBoots])].map(n => [n, hint(BUILD.boots, n)]),
    // Never recommend anti-heal items, even if they show up in your games
    situational: [...new Set([...d.situational, ...BUILD.extraSituational])].filter(n => !ANTI_HEAL.includes(n)).map(n => [n, hint(BUILD.situational, n)]),
    summoners: BUILD.summoners,
    skillOrder,
    skillPriority: "R > " + ["Q", "W", "E"].sort((a, b) => maxAt(a) - maxAt(b)).join(" > "),
    skillNote: d.skillOrder && d.skillOrder.length ? "Your usual skill order." : "Not enough timeline data; showing the guide default."
  };
}

/* Which option each clickable rune shows, keyed "page|slot" */
const runeChoice = {};
let runeTab = 0;
$("#buildGrid")?.addEventListener("click", e => {
  const tab = e.target.closest("[data-rune-tab]");
  if (tab) { runeTab = +tab.dataset.runeTab; renderBuild(); $(`[data-rune-tab="${runeTab}"]`).focus(); return; }
  const b = e.target.closest(".has-opt");
  if (!b) return;
  const slot = b.dataset.slot, key = b.dataset.page + "|" + slot;
  runeChoice[key] = (runeChoice[key] || 0) + 1;
  renderBuild();
  $(`.has-opt[data-slot="${slot}"]`)?.focus();
});
$("#buildGrid")?.addEventListener("keydown", e => {
  if (!e.target.closest("[data-rune-tab]") || !["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown", "Home", "End"].includes(e.key)) return;
  e.preventDefault();
  const n = activeBuild().runes.length;
  runeTab = e.key === "Home" ? 0 : e.key === "End" ? n - 1 : (runeTab + (["ArrowRight", "ArrowDown"].includes(e.key) ? 1 : -1) + n) % n;
  renderBuild();
  $(`[data-rune-tab="${runeTab}"]`).focus();
});

function renderBuild() {
  const BUILD = activeBuild();
  const runeIcon = n => ICONS.rune && ICONS.rune[n] ? `<img src="${ICONS.rune[n]}" alt="">` : "";
  const r = BUILD.runes[runeTab];
  const runeRow = (p, slot) => {
    const choices = [p, ...((r.options || {})[p] || [])];
    const shown = choices[(runeChoice[r.name + "|" + slot] || 0) % choices.length];
    const note = (r.notes || {})[shown];
    const inner = `${runeIcon(shown)}<span class="b-txt"><b>${esc(shown)}</b>${shown !== p ? `<small>Instead of ${esc(p)}</small>` : ""}${note ? `<small>${esc(note)}</small>` : ""}</span>`;
    if (choices.length < 2) return `<li class="b-rune${slot === 0 ? " b-keystone" : ""}">${inner}</li>`;
    return `<li><button type="button" class="b-rune has-opt${shown !== p ? " swapped" : ""}" data-page="${esc(r.name)}" data-slot="${slot}" aria-label="${esc(shown)}. Swap to ${esc(choices[(choices.indexOf(shown) + 1) % choices.length])}">${inner}<span class="b-swap">Swap</span></button></li>`;
  };
  const tree = (t, rows) => `<div class="b-tree"><h4>${runeIcon(t)}${esc(t)}</h4><ul>${rows}</ul></div>`;
  const tabs = BUILD.runes.map((x, i) => `<button type="button" role="tab" id="runeTab${i}" class="b-tab" data-rune-tab="${i}" aria-selected="${i === runeTab}" aria-controls="runePanel" tabindex="${i === runeTab ? 0 : -1}">${runeIcon(x.name)}<span><b>${esc(x.name)}</b><small>${esc(x.when)}</small></span></button>`).join("");
  const many = BUILD.runes.length > 1;
  const anySwap = BUILD.runes.some(x => x.options);
  const panel = `<div class="b-panel" id="runePanel"${many ? ` role="tabpanel" aria-labelledby="runeTab${runeTab}"` : ""}>
    <p class="b-when${many ? "" : " show"}"><b>Use when:</b> ${esc(r.when)}</p>
    ${tree(r.primaryTree, r.primary.map((p, i) => runeRow(p, i)).join(""))}
    ${tree(r.secondaryTree, r.secondary.map((p, i) => runeRow(p, "s" + i)).join(""))}
    <div class="b-tree"><h4>Shards</h4><ul>${r.shards.map(p => `<li class="b-rune small">${runeIcon(p)}<span class="b-txt"><b>${p === "Health" ? "Flat HP" : esc(p)}</b></span></li>`).join("")}</ul></div>
    ${r.name === "Stormraider's Surge" && STORM_PLAN ? `<div class="storm-plan b-wide"><b>How to trade:</b> ${STORM_PLAN}</div>` : ""}
  </div>`;
  const item = ([a, b]) => `<li class="b-item"><div class="b-ico">${itemIcons(a)}</div><div class="b-txt"><b>${esc(a)}</b>${b ? `<small>${esc(b.replace(/^3rd item: /, ""))}</small>` : ""}</div></li>`;
  const step = (n, title, rows) => `<li class="b-step"><h4><span>${n}</span>${title}</h4><ul>${rows.map(item).join("")}</ul></li>`;
  const summ = (BUILD.summoners || []).map(([a, b]) => `<li><b>${esc(a)}</b> · ${esc(b)}</li>`).join("");
  let skills = `<div class="lbl"></div>` + BUILD.skillOrder.map((_, i) => `<div class="lvl">${i + 1}</div>`).join("");
  for (const k of ["Q", "W", "E", "R"]) {
    skills += `<div class="lbl">${k}</div>` + BUILD.skillOrder.map(x => `<div class="${x === k ? "on" + (k === "R" ? " r" : "") : ""}">${x === k ? k : ""}</div>`).join("");
  }
  $("#buildGrid").innerHTML = `
    <div class="b-block"><h3>Runes</h3><p class="b-sub">${many ? "Pick a page by matchup. " : ""}${anySwap ? "Tap a rune marked Swap to see the alternative." : ""}</p>
      ${many ? `<div class="b-tabs" role="tablist" aria-label="Rune pages" style="--n:${BUILD.runes.length}">${tabs}</div>` : ""}${panel}</div>
    <div class="b-block"><div class="b-head"><h3>Items</h3></div>${summ ? `<ul class="b-summs" aria-label="Summoner spells">${summ}</ul>` : ""}
      <ol class="b-path">${step(1, "Start", BUILD.starting)}${step(2, "Core items", BUILD.core.slice(0, 2))}${step(3, "Alternative first item", BUILD.core.slice(2))}</ol>
      <div class="b-more">
        <div class="b-step"><h4>Boots</h4><ul>${BUILD.boots.map(item).join("")}</ul></div>
        <div class="b-step"><h4>${MY_DATA ? "Later items" : "Situational"}</h4><ul class="two">${BUILD.situational.map(item).join("")}</ul></div>
      </div></div>
    <div class="b-block"><div class="b-head"><h3>Skill order</h3><span class="b-max">Max order <b>${esc(BUILD.skillPriority)}</b></span></div>
      <div class="card build-card"><div class="skill-order" id="skillOrder">${skills}</div><p class="note">${esc(BUILD.skillNote)}</p></div></div>`;
}

/* How I play: show one chapter at a time */
if ($(".p-rail")) {
  const tabs = [...document.querySelectorAll(".p-rail [role=tab]")];
  const show = (i, focus) => {
    tabs.forEach((t, n) => {
      const on = n === i;
      t.setAttribute("aria-selected", on);
      t.tabIndex = on ? 0 : -1;
      document.getElementById(t.dataset.ch).hidden = !on;
    });
    history.replaceState(null, "", "#" + tabs[i].dataset.ch);
    if (focus) tabs[i].focus();
  };
  $(".p-rail").addEventListener("click", e => { const t = e.target.closest("[role=tab]"); if (t) show(tabs.indexOf(t), true); });
  $(".p-rail").addEventListener("keydown", e => {
    const i = tabs.indexOf(e.target);
    const next = { ArrowDown: i + 1, ArrowRight: i + 1, ArrowUp: i - 1, ArrowLeft: i - 1, Home: 0, End: tabs.length - 1 }[e.key];
    if (next === undefined) return;
    e.preventDefault();
    show((next + tabs.length) % tabs.length, true);
  });
  document.querySelectorAll(".p-next").forEach(b => b.addEventListener("click", () => {
    show(tabs.findIndex(t => t.dataset.ch === b.dataset.go), true);
    $(".p-layout").scrollIntoView({ block: "start" });
  }));
  const start = tabs.findIndex(t => t.dataset.ch === location.hash.slice(1));
  if (start > 0) show(start);
}

/* ---------- Matchup tier board ---------- */
function diffCell(d) {
  const t = tier(d);
  const pips = Array.from({ length: 5 }, (_, i) => `<i class="${i < d ? "f" : ""}"></i>`).join("");
  return `<span class="diff ${t}" title="${tierLabel[t]}"><span class="pips">${pips}</span>${d} · ${tierLabel[t]}</span>`;
}
function findMatchups(q) {
  const n = normName(q);
  if (!n) return [];
  const exact = MATCHUPS.filter(m => normName(m.champion) === n);
  if (exact.length) return exact;
  const starts = MATCHUPS.filter(m => normName(m.champion).startsWith(n));
  return starts.length ? starts : MATCHUPS.filter(m => normName(m.champion).includes(n));
}
const BANS = ["Renekton", "Garen", "Vayne", "Malphite", "Wukong"]; // first one is the ban I use
const TIERS = ["easy", "even", "hard", "vhard"];
const boardOrder = TIERS.flatMap(t => MATCHUPS.filter(m => tier(m.difficulty) === t).sort((a, b) => a.champion.localeCompare(b.champion)));
function renderBoard() {
  $("#mtBoard").innerHTML = TIERS.map(t => {
    const rows = boardOrder.filter(m => tier(m.difficulty) === t);
    return `<section class="mt-band ${t}" aria-label="${tierLabel[t]} matchups"><h3>${tierLabel[t]}<small>${rows.length} champions</small></h3><div class="mt-tiles">${rows.map(m => {
      const ban = BANS.indexOf(m.champion);
      return `<button type="button" class="mt-tile" data-c="${normName(m.champion)}">${ban < 0 ? "" : `<em>${ban === 0 ? "My ban" : "Ban"}</em>`}${ICONS.champ[m.champion] ? `<img src="${ICONS.champ[m.champion]}" width="48" height="48" alt="">` : ""}${esc(m.champion)}</button>`;
    }).join("")}</div></section>`;
  }).join("");
  $("#mtCount").textContent = `${MATCHUPS.length} matchups`;
}
const tipBullets = t => `<ul>${String(t).replace(/([.!?])\s+(?=[A-Z])/g, "$1\n").split("\n").map(x => `<li>${esc(x)}</li>`).join("")}</ul>`;
function openMatchup(m) {
  history.replaceState(null, "", "#" + normName(m.champion));
  const storm = m.keystone === "Stormraider's Surge" && STORM_PLAN;
  $("#mtSheet").innerHTML = `
    <div class="mt-nav"><div><button type="button" data-go="-1" aria-label="Previous champion">←</button><button type="button" data-go="1" aria-label="Next champion">→</button></div><button type="button" data-close>Close</button></div>
    <div class="qcard">
      <div class="qhead">
        ${ICONS.champ[m.champion] ? `<img src="${ICONS.champ[m.champion]}" alt="">` : ""}
        <div><h3 id="mtName">${esc(m.champion)}</h3>${diffCell(m.difficulty)}</div>
      </div>
      <dl>
        <div><dt>Setup</dt><dd class="setup-line"><b class="ks">${ksIcon(m.keystone)}${esc(m.keystone)}</b><span class="item-label">${itemIcons(m.start)}${esc(m.start)}</span><span>Flash + ${esc(m.summoner)}</span></dd></div>
        ${storm ? `<div><dt>Trade</dt><dd>${STORM_PLAN}</dd></div>` : ""}
        <div><dt>Key ability</dt><dd>${esc(m.dodge)}</dd></div>
        <div><dt>Lane plan (1–6)</dt><dd>${esc(m.lanePlan)}</dd></div>
        <div><dt>Power spikes</dt><dd>${esc(m.spikes)}</dd></div>
        <div><dt>Win condition</dt><dd>${esc(m.winCondition)}</dd></div>
        <div><dt>Tips</dt><dd>${tipBullets(m.notes)}</dd></div>
      </dl>
    </div>`;
  $("#mtSheet").dataset.i = boardOrder.indexOf(m);
  const d = $("#mtDrawer");
  if (!d.open) d.showModal();
  d.scrollTop = 0;
}
$("#mtBoard")?.addEventListener("click", e => {
  const b = e.target.closest(".mt-tile");
  if (b) openMatchup(boardOrder.find(m => normName(m.champion) === b.dataset.c));
});
$("#mtSheet")?.addEventListener("click", e => {
  const go = e.target.closest("[data-go]");
  if (go) {
    const n = boardOrder.length;
    openMatchup(boardOrder[(+$("#mtSheet").dataset.i + +go.dataset.go + n) % n]);
    $(`[data-go="${go.dataset.go}"]`).focus();
  }
  if (e.target.closest("[data-close]")) $("#mtDrawer").close();
});
$("#mtDrawer")?.addEventListener("click", e => { if (e.target === e.currentTarget) e.currentTarget.close(); });
$("#mtDrawer")?.addEventListener("close", () => history.replaceState(null, "", location.pathname + location.search));
$("#mtSearch")?.addEventListener("input", e => {
  const hits = new Set(findMatchups(e.target.value).map(m => normName(m.champion)));
  const q = e.target.value.trim();
  document.querySelectorAll(".mt-tile").forEach(t => {
    const dim = !!q && !hits.has(t.dataset.c);
    t.classList.toggle("dim", dim);
    t.tabIndex = dim ? -1 : 0;
    t.setAttribute("aria-hidden", dim);
  });
  $("#mtCount").textContent = q ? `${hits.size} of ${MATCHUPS.length} matchups` : `${MATCHUPS.length} matchups`;
});
$("#mtSearch")?.addEventListener("keydown", e => {
  if (e.key !== "Enter") return;
  const [m] = findMatchups(e.target.value);
  if (m) { e.preventDefault(); openMatchup(m); }
});
function openFromHash() {
  const m = boardOrder.find(x => normName(x.champion) === location.hash.slice(1));
  if (m) openMatchup(m);
}
if ($("#mtBoard")) addEventListener("hashchange", openFromHash);

/* ---------- Personal data (MY_DATA) ---------- */
function applyPersonal() {
  if (!MY_DATA) return;
  // Use what you run in matchups you've played, except fields the guide locks
  for (const m of MATCHUPS) {
    const r = myRec(m);
    if (!r) continue;
    const locked = m.lock || [];
    if (r.keystone && !locked.includes("keystone")) m.keystone = r.keystone;
    if (r.start && !locked.includes("start")) m.start = r.start.split(" + ").filter(x => !/Potion/.test(x)).join(" + ");
  }
  if ($("#buildLead")) $("#buildLead").textContent = "Built from my own ranked Camille games: the runes, items, summoners and skill order I actually use.";
}

/* ---------- Init ---------- */
applyPersonal();
if ($("#kitGrid")) renderKit();
if ($("#comboGrid")) renderCombos();
if ($("#buildGrid")) renderBuild();
if ($("#mtBoard")) { renderBoard(); openFromHash(); }
if ($("#statCount")) { $("#statCount").textContent = MATCHUPS.length; $("#statPatch").textContent = SITE.patch.split(" ")[0]; }
$("#footPatch").textContent = SITE.patch;$("#footUpdated").textContent = SITE.lastUpdated;
